
.character-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.char-header {
  text-align: center;
  padding-bottom: 10px;
  border-bottom: 1px dashed var(--c-shadow);
}

.char-name {
  font-size: 1.1rem;
  font-weight: bold;
  color: var(--c-ghost);
  letter-spacing: 1px;
}

.char-title {
  font-size: 0.8rem;
  color: var(--c-pale);
  margin-top: 2px;
}

.affection-section {
  background: rgba(0, 0, 0, 0.3);
  padding: 10px;
  border-radius: 4px;
}

.affection-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.affection-label {
  font-size: 0.85rem;
  color: var(--c-obsession);
  font-weight: 500;
}

.affection-stage {
  font-size: 0.7rem;
  padding: 2px 6px;
  border-radius: 3px;
  font-weight: 500;

  &.stage-1 {
    background: rgba(100, 100, 100, 0.4);
    color: #aaa;
  }
  &.stage-2 {
    background: rgba(100, 130, 180, 0.3);
    color: #8fb8d8;
  }
  &.stage-3 {
    background: rgba(180, 130, 180, 0.3);
    color: #d88fd8;
  }
  &.stage-4 {
    background: rgba(201, 74, 122, 0.4);
    color: #ff8fb8;
  }
  &.stage-5 {
    background: rgba(139, 41, 66, 0.6);
    color: #ff6b8a;
    animation: pulse 1.5s infinite;
  }
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

.affection-bar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.affection-track {
  flex: 1;
  height: 8px;
  background: var(--c-void);
  border: 1px solid var(--c-shadow);
  border-radius: 4px;
  overflow: hidden;
}

.affection-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-corrupt), var(--c-obsession));
  border-radius: 3px;
  transition: width 0.5s ease;
}

.affection-value {
  font-size: 0.85rem;
  font-weight: bold;
  color: var(--c-obsession);
  min-width: 25px;
  text-align: right;
}

.inner-voice {
  background: rgba(107, 58, 107, 0.15);
  border: 1px solid var(--c-corrupt);
  border-radius: 4px;
  padding: 10px;
}

.voice-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--c-pale);
  margin-bottom: 8px;
}

.icon {
  font-size: 1rem;
}

.voice-content {
  font-size: 0.85rem;
  color: var(--c-ghost);
  font-style: italic;
  line-height: 1.5;
  padding-left: 8px;
  border-left: 2px solid var(--c-corrupt);
}
